    {
     "k": "service-periodic-maintenance.banner.text",
     "t": "text",
     "l": "Banner text",
     "v": "Scheduled servicing to the Maruti Suzuki interval chart, with a printed job card and nothing done that you have not approved."
    },
    {
     "k": "service-periodic-maintenance.banner.photo",
     "t": "image",
     "l": "Banner photograph",
     "v": "../assets/images/banners/periodic-maintenance.jpg"
    },
    {
     "k": "service.periodic-maintenance.faq.0.q",
     "t": "text",
     "l": "Question 1",
     "v": "How often should I service my car?"
    },
    {
     "k": "service.periodic-maintenance.faq.0.a",
     "t": "text",
     "l": "Answer 1",
     "v": "Maruti Suzuki's schedule is every 10,000 km or 12 months, whichever comes first, for most current petrol models. CNG and older models differ — tell us the model and year and we will confirm the exact interval."
    },
    {
     "k": "service.periodic-maintenance.faq.1.q",
     "t": "text",
     "l": "Question 2",
     "v": "Will servicing elsewhere void my warranty?"
    },
    {
     "k": "service.periodic-maintenance.faq.1.a",
     "t": "text",
     "l": "Answer 2",
     "v": "Warranty terms require servicing at an authorised workshop within the prescribed intervals using genuine parts. Servicing outside that network can put a claim at risk. We are an authorised Maruti Suzuki workshop."
    },
    {
     "k": "service.periodic-maintenance.faq.2.q",
     "t": "text",
     "l": "Question 3",
     "v": "Do you give an estimate first?"
    },
    {
     "k": "service.periodic-maintenance.faq.2.a",
     "t": "text",
     "l": "Answer 3",
     "v": "Always. You approve the estimate before work starts, and we call you for approval before adding anything to it."
    },
    {
     "k": "service-body-shop.banner.heading",
     "t": "rich",
     "l": "Banner heading",
     "v": "Body Shop and Accident Repair"
    },
    {
     "k": "service-body-shop.banner.text",
     "t": "text",
     "l": "Banner text",
     "v": "Panel work, denting and painting in a controlled booth, with the insurance claim handled end to end on your behalf."
    },
    {
     "k": "service-body-shop.banner.photo",
     "t": "image",
     "l": "Banner photograph",
     "v": "../assets/images/banners/body-shop.jpg"
    },
    {
     "k": "service.body-shop.faq.0.q",
     "t": "text",
     "l": "Question 1",
     "v": "Do you handle the insurance claim?"
    },
    {
     "k": "service.body-shop.faq.0.a",
     "t": "text",
     "l": "Answer 1",
     "v": "Yes. We coordinate the surveyor visit, submit the estimate and documents and follow the claim through. With cashless-approved insurers you settle only your excess and any non-payable items."
    },
    {
     "k": "service.body-shop.faq.1.q",
     "t": "text",
     "l": "Question 2",
     "v": "How long does accident repair take?"
    },
    {
     "k": "service.body-shop.faq.1.a",
     "t": "text",
     "l": "Answer 2",
     "v": "Light cosmetic work is usually two to four days. Structural repair depends on parts availability and how quickly the surveyor approves — we give you a date once the survey is done, and tell you if it moves."
    },
    {
     "k": "service-parts-accessories.banner.heading",
     "t": "rich",
     "l": "Banner heading",
     "v": "Genuine Parts and Accessories"
    },
    {
     "k": "service-parts-accessories.banner.text",
     "t": "text",
     "l": "Banner text",
     "v": "Maruti Genuine Parts over the counter, plus an accessory range fitted and warranted by us rather than by a roadside shop."
    },
    {
     "k": "service-parts-accessories.banner.photo",
     "t": "image",
     "l": "Banner photograph",
     "v": "../assets/images/banners/parts-accessories.jpg"
    },
    {
     "k": "service.parts-accessories.faq.0.q",
     "t": "text",
     "l": "Question 1",
     "v": "Can I buy parts without booking a service?"
    },
    {
     "k": "service.parts-accessories.faq.0.a",
     "t": "text",
     "l": "Answer 1",
     "v": "Yes. The parts counter is open through workshop hours for over-the-counter sales. Bring your registration number so we can confirm the exact variant."
    },
    {
     "k": "service.parts-accessories.faq.1.q",
     "t": "text",
     "l": "Question 2",
     "v": "Are accessories covered by warranty?"
    },
    {
     "k": "service.parts-accessories.faq.1.a",
     "t": "text",
     "l": "Answer 2",
     "v": "Maruti Genuine Accessories fitted by us carry their own warranty and do not affect your vehicle warranty. Accessories fitted elsewhere can affect a claim where they involve wiring or bodywork."
    },
    {
     "k": "service-extended-warranty.banner.heading",
     "t": "rich",
     "l": "Banner heading",
     "v": "Extended Warranty and Service Plans"
    },
    {
     "k": "service-extended-warranty.banner.text",
     "t": "text",
     "l": "Banner text",
     "v": "Cover beyond the standard warranty period, and pre-paid service packages that fix today's rates for years ahead."
    },
    {
     "k": "service-extended-warranty.banner.photo",
     "t": "image",
     "l": "Banner photograph",
     "v": "../assets/images/banners/extended-warranty.jpg"
    },
    {
     "k": "service.extended-warranty.faq.0.q",
     "t": "text",
     "l": "Question 1",
     "v": "When should I buy extended warranty?"
    },
    {
     "k": "service.extended-warranty.faq.0.a",
     "t": "text",
     "l": "Answer 1",
     "v": "Before the standard warranty expires. Once it has lapsed the options narrow and the vehicle usually needs inspecting first."
    },
    {
     "k": "service.extended-warranty.faq.1.q",
     "t": "text",
     "l": "Question 2",
     "v": "Does it transfer if I sell the car?"
    },
    {
     "k": "service.extended-warranty.faq.1.a",
     "t": "text",
     "l": "Answer 2",
     "v": "Yes, and it is worth putting in the advertisement — a buyer taking on a car with warranty remaining will usually pay more for it."
    }
